  "meta": {
    "strategy_used": "mnemonic",
    "final_answer": "$8\\pi r^2$",
    "verify_code": "import sympy as sp\nr = sp.symbols('r')\n# Bereken die radiale en oppervlaktes\nbuiten_radius = 3*r\nbuiten_area = sp.pi * (buiten_radius)**2\nbin_area = sp.pi * (r)**2\nblomtuin_area = buiten_area - bin_area\nprint(f\"{blomtuin_area/sp.pi}\\pi\")",
    "techniques": ["draw_a_diagram", "factor_tree"]
  }
}

